// ELF backend v0 (ADR 0004, phase 5a) — see elf_backend.hpp.
//
// The scheduling (frames, scope handling, loop labels, pending-alignment
// arithmetic, call plans) mirrors the P3 asm backend so behaviour stays in
// lockstep; the difference is that each instruction goes through the encoder
// into a byte buffer and labels are ids patched to rel32.
// Generated by tools/elfrtgen at build time: the freestanding runtime image
// (runtime/elfrt/enc_rt.c) plus the offsets of its public symbols inside it.
#include "encrt_blob.cpp"

#include "elf_backend.hpp"
#include "encoder.hpp"
#include "elf_writer.hpp"

#include "../ast.hpp"
#include "../backend.hpp"
#include "../ir.hpp"
#include "../type_resolver.hpp"

#include <algorithm>
#include <functional>
#include <map>
#include <memory>
#include <string>
#include <vector>

namespace backend {
namespace {

// SysV word argument registers, in order (v0: at most 6 arguments).
const int CALL_REGS[6] = {RDI, RSI, RDX, RCX, R8, R9};

bool is_word(TypeKind k) {
    return k == TypeKind::Int || k == TypeKind::Bool || k == TypeKind::Char;
}

struct LoopTargets {
    int brk = -1;
    int cont = -1;
};

// One emission context = one function frame.
struct Ctx {
    int label_id = -1;                     // position of the function body
    int ret_label = -1;                    // position of the epilogue reload
    std::map<std::string, int> locals;     // name -> rbp offset of its slot
    int slots = 0;                         // allocated 8-byte slots
    int frame = 0;                         // final rsp sub, 16-aligned
    int pending = 0;                       // outstanding 8-byte pushes
    std::vector<LoopTargets> loops;
    int ret_slot = 0;                      // parked return value (all contexts)
    TypeKind ret_kind = TypeKind::Unknown;
    bool is_main_body = false;
};

class ElfBackend {
public:
    ElfBackend(Program& program, const std::string& source)
        : program_(program), source_file_(source) {}

    ~ElfBackend() {
        for (auto& [fn, c] : fn_ctx_) delete c;
    }

    std::vector<uint8_t> run() {
        TypeResolver resolver;
        resolver.resolve(program_);

        auto program_ir = ir::build(program_.statements);

        // User functions; lambdas/generic templates/nested fns reject at
        // their declaration with the source line.
        for (auto& top : program_ir) {
            if (top->kind != ir::SKind::FuncDecl) continue;
            auto* fn = static_cast<FunctionDecl*>(top->ast);
            if (!fn->type_params.empty())
                err(fn->line, "elf backend v0: generics are not supported (build with -b c)");
            if (fn->is_lambda || !fn->captures.empty())
                err(fn->line, "elf backend v0: closures/lambdas are not supported (build with -b c)");
            fns_.push_back(fn);
            fns_by_name_[fn->name] = fn;
            if (fn->name == "main") main_fn_ = fn;
        }
        if (main_fn_) {
            if (!main_fn_->params.empty())
                err(main_fn_->line, "elf backend v0: main cannot take parameters");
            if (main_fn_->has_return_type && !is_word(main_fn_->return_type))
                err(main_fn_->line, "elf backend v0: main must return int or nothing");
        }

        // Encoder labels for the runtime-image symbols are reserved up front
        // so call sites can reference them during generation.
        for (unsigned long i = 0; i < encrt_syms_count; i++)
            rt_ids_[encrt_syms[i].name] = E_.new_label();

        // ── layout pass: every context pre-allocates its slots so frames are
        //    known before the first emitted instruction of the body.
        ctx_main_.label_id = E_.new_label();
        ctx_main_.ret_label = E_.new_label();
        ctx_main_.is_main_body = true;
        scan_list(ctx_main_, program_ir, /*skip_fns=*/true);
        if (main_fn_) {
            auto main_ir = ir::build(main_fn_->body);
            scan_list(ctx_main_, main_ir, false);
        }
        finish_frame(ctx_main_);
        for (auto* fn : fns_) {
            if (fn == main_fn_) continue;
            check_fn_signature(fn);
            auto* c = new Ctx{};
            c->label_id = E_.new_label();
            c->ret_label = E_.new_label();
            c->ret_kind = fn->has_return_type ? fn->return_type : TypeKind::Unknown;
            for (auto& p : fn->params) declare_slot(*c, p.name, fn->line);
            fn_ctx_[fn] = c;
            auto body_ir = ir::build(fn->body);
            scan_list(*c, body_ir, false);
            finish_frame(*c);
        }

        // ── emit ──
        emit_entry_stub();
        bind(ctx_main_.label_id);
        emit_frame_head(ctx_main_);
        for (auto& top : program_ir) {
            if (top->kind != ir::SKind::FuncDecl) emit_node(ctx_main_, *top);
        }
        if (main_fn_) {
            auto body_ir = ir::build(main_fn_->body);
            for (auto& n : body_ir) emit_node(ctx_main_, *n);
        }
        emit_frame_tail(ctx_main_);

        for (auto* fn : fns_) {
            if (fn == main_fn_) continue;
            emit_function(fn);
        }

        // ── append the freestanding runtime image verbatim ──
        size_t gen_len = code_.size();
        code_.resize(gen_len + (size_t)encrt_image_len, 0);
        std::copy(encrt_image, encrt_image + encrt_image_len,
                  code_.begin() + static_cast<long>(gen_len));
        for (unsigned long i = 0; i < encrt_syms_count; i++)
            bind_at(rt_ids_[encrt_syms[i].name], gen_len + (size_t)encrt_syms[i].off);

        std::string enc_err;
        if (!E_.finish(&enc_err)) err(0, enc_err);

        // ── ELF wrap: single flat RX segment, entry at the stub ──
        ElfWriter w;
        return w.build(code_, /*entry_offset=*/0);
    }

private:
    Program& program_;
    std::string source_file_;

    std::vector<uint8_t> code_;
    Encoder E_{code_};

    std::vector<FunctionDecl*> fns_;
    std::map<std::string, FunctionDecl*> fns_by_name_;
    FunctionDecl* main_fn_ = nullptr;

    Ctx ctx_main_;
    std::map<FunctionDecl*, Ctx*> fn_ctx_;
    std::map<const void*, std::pair<int, int>> loop_slots_;  // LoopStmt* -> (count, i)

    Ctx* ctx_ = nullptr;   // current context during emit/scan helpers
    std::map<const void*, int> decl_slots_;   // VarDecl* -> frame offset
    std::map<std::string, int> rt_ids_;       // runtime symbol -> encoder label

    // ── diagnostics ─────────────────────────────────────────────────────────
    [[noreturn]] void err(int line, const std::string& msg) const {
        throw CompileError(line, msg);
    }

    // ── encoder labels ──────────────────────────────────────────────────────
    int new_label() { return E_.new_label(); }
    void bind(int id) { E_.bind(id); }
    void bind_at(int id, size_t at) { E_.bind_at(id, at); }

    // ── frame layout ─────────────────────────────────────────────────────────
    void declare_slot(Ctx& c, const std::string& name, int line) {
        if (c.locals.count(name))
            err(line, "elf backend v0: duplicate declaration '" + name + "' in one function (shadowing is not supported)");
        c.slots++;
        c.locals[name] = -8 * c.slots;
    }

    void scan_list(Ctx& c, const std::vector<std::unique_ptr<ir::Node>>& list, bool skip_fns) {
        for (auto& n : list) scan_node(c, *n, skip_fns);
    }

    void scan_node(Ctx& c, const ir::Node& n, bool skip_fns) {
        ctx_ = &c;
        switch (n.kind) {
            case ir::SKind::FuncDecl:
                if (!skip_fns)
                    err(n.ast->line, "elf backend v0: nested functions are not supported");
                return;
            case ir::SKind::VarDecl: {
                auto* v = static_cast<VarDecl*>(n.ast);
                TypeKind vt = v->annotation == TypeKind::Unknown
                                  ? (v->initializer ? v->initializer->resolved_type : TypeKind::Int)
                                  : v->annotation;
                if (!is_word(vt) || !v->tuple_members.empty())
                    err(v->line, "elf backend v0: variable type of '" + v->name + "' is unsupported (int/bool/char only)");
                if (v->initializer) scan_expr(c, v->initializer.get());
                // every declaration gets its own frame slot; the name is
                // bound by scope (restore logic lives in scan_scope)
                if (c.locals.count(v->name))
                    err(v->line, "elf backend v0: duplicate declaration '" + v->name + "' in one scope");
                c.slots++;
                decl_slots_[v] = -8 * c.slots;
                c.locals[v->name] = -8 * c.slots;
                return;
            }
            case ir::SKind::Assign: {
                auto* s = static_cast<AssignStmt*>(n.ast);
                if (s->rhs) scan_expr(c, s->rhs.get());
                return;
            }
            case ir::SKind::ExprStmt: {
                auto* s = static_cast<ExprStmt*>(n.ast);
                scan_expr(c, s->expr.get());
                return;
            }
            case ir::SKind::Print: {
                auto* s = static_cast<PrintStmt*>(n.ast);
                for (auto& e : s->args) scan_expr(c, e.get());
                return;
            }
            case ir::SKind::Return: {
                auto* s = static_cast<ReturnStmt*>(n.ast);
                for (auto& v : s->values) scan_expr(c, v.get());
                return;
            }
            case ir::SKind::If: {
                auto* s = static_cast<IfStmt*>(n.ast);
                scan_expr(c, s->condition.get());
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                if (s->has_else) scan_scope(c, [&] {
                    for (auto& b : n.else_body) scan_node(c, *b, skip_fns);
                });
                return;
            }
            case ir::SKind::While: {
                auto* s = static_cast<WhileStmt*>(n.ast);
                scan_expr(c, s->condition.get());
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                return;
            }
            case ir::SKind::DoWhile: {
                auto* s = static_cast<DoWhileStmt*>(n.ast);
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                scan_expr(c, s->condition.get());
                return;
            }
            case ir::SKind::For: {
                // the header declaration is scoped to header + body
                auto* s = static_cast<ForStmt*>(n.ast);
                std::string hdr;
                bool had = false;
                int prev = 0;
                if (n.init && n.init->kind == ir::SKind::VarDecl) {
                    hdr = static_cast<VarDecl*>(n.init->ast)->name;
                    auto it = c.locals.find(hdr);
                    if (it != c.locals.end()) { had = true; prev = it->second; }
                }
                if (n.init) scan_node(c, *n.init, skip_fns);
                if (s->condition) scan_expr(c, s->condition.get());
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                if (n.update) scan_node(c, *n.update, skip_fns);
                if (had) c.locals[hdr] = prev;
                else if (!hdr.empty()) c.locals.erase(hdr);
                return;
            }
            case ir::SKind::Loop: {
                auto* l = static_cast<LoopStmt*>(n.ast);
                scan_expr(c, l->count.get());
                c.slots++;
                int cnt = -8 * c.slots;
                c.slots++;
                int ctr = -8 * c.slots;
                loop_slots_[l] = {cnt, ctr};
                scan_scope(c, [&] {
                    for (auto& b : n.body) scan_node(c, *b, skip_fns);
                });
                return;
            }
            default:
                return;
        }
    }

    // Runs the scan of a nested block scope, then unbinds every name the
    // block declared (HMX block scoping: sibling blocks may redeclare).
    template <typename F>
    void scan_scope(Ctx& c, F&& f) {
        std::map<std::string, int> before(c.locals);
        f();
        for (auto it = c.locals.begin(); it != c.locals.end();) {
            if (before.count(it->first) == 0) it = c.locals.erase(it);
            else ++it;
        }
    }

    // Pre-scan of expressions: no slot needs live in v0 (pure word
    // evaluation leaves results in registers). Unknown expression shapes are
    // ignored — the emit pass reports them with a line number.
    void scan_expr(Ctx& c, Expression* e) {
        if (!e) return;
        if (auto* bin = dynamic_cast<BinaryExpr*>(e)) {
            scan_expr(c, bin->left.get());
            scan_expr(c, bin->right.get());
            return;
        }
        if (auto* n = dynamic_cast<NotExpr*>(e)) { scan_expr(c, n->operand.get()); return; }
        if (auto* n = dynamic_cast<NegExpr*>(e)) { scan_expr(c, n->operand.get()); return; }
        if (auto* cond = dynamic_cast<ConditionalExpr*>(e)) {
            scan_expr(c, cond->condition.get());
            scan_expr(c, cond->then_expr.get());
            scan_expr(c, cond->else_expr.get());
            return;
        }
        if (auto* cst = dynamic_cast<CastExpr*>(e)) { scan_expr(c, cst->operand.get()); return; }
        if (auto* call = dynamic_cast<CallExpr*>(e)) {
            for (auto& a : call->args) scan_expr(c, a.get());
            return;
        }
    }

    void finish_frame(Ctx& c) {
        // Every context parks its return value in a dedicated slot; the
        // epilogue reloads it into rax (main uses it for the exit code).
        c.slots++;
        c.ret_slot = -8 * c.slots;
        int bytes = (c.slots * 8 + 15) & ~15;   // 16-align
        c.slots = bytes / 8;
        c.frame = bytes;
    }

    void emit_frame_head(Ctx& c) {
        E_.push_r(RBP);
        E_.mov_r_r(RBP, RSP);
        E_.alu_ri(ALU_SUB, RSP, c.frame);
        // zero the ret slot: a bare `return` (or a loop-body re-entry) must
        // still produce a defined exit value for the frame tail reload.
        E_.mov_r_imm(RAX, 0);
        E_.mov_mem_r(RBP, c.ret_slot, RAX);
    }

    void emit_frame_tail(Ctx& c) {
        bind(c.ret_label);
        E_.mov_r_mem(RAX, RBP, c.ret_slot);
        E_.leave();
        E_.ret();
    }

    // ── entry stub: call main context, exit_group(result) ──
    void emit_entry_stub() {
        E_.alu_rr(ALU_XOR, RBP, RBP);   // rbp = 0 defensively
        E_.call(ctx_main_.label_id);
        E_.mov_r_r(RDI, RAX);
        E_.mov_eax_imm(231);            // SYS_exit_group
        E_.syscall();
    }

    // ── runtime helper calls ─────────────────────────────────────────────────
    int rt_label(const std::string& name, int line) {
        auto it = rt_ids_.find(name);
        if (it == rt_ids_.end())
            err(line, "elf backend v0: runtime symbol '" + name + "' is not in the runtime image");
        return it->second;
    }

    // Calls realign to 16 when mid-expression pushes are outstanding.
    void emit_call(int target) {
        if (ctx_->pending % 2 != 0) E_.alu_ri(ALU_SUB, RSP, 8);
        E_.call(target);
        if (ctx_->pending % 2 != 0) E_.alu_ri(ALU_ADD, RSP, 8);
    }

    // Byte write of a constant via the 1-byte runtime helper (separators).
    void emit_wchr_imm(int c) {
        E_.mov_edi_imm(c);
        emit_call(rt_label("_hmx_w_char", 0));
    }

    // ── expression compilation (word-only; result in rax) ───────────────────
    void compile_expr(Expression* e) {
        if (auto* num = dynamic_cast<NumberLiteral*>(e)) {
            E_.mov_r_imm(RAX, static_cast<int64_t>(num->value));
            return;
        }
        if (auto* ch = dynamic_cast<CharLiteral*>(e)) {
            E_.mov_r_imm(RAX, static_cast<int64_t>(static_cast<int>(ch->value)));
            return;
        }
        if (auto* b = dynamic_cast<BoolLiteral*>(e)) {
            E_.mov_r_imm(RAX, b->value ? 1 : 0);
            return;
        }
        if (auto* id = dynamic_cast<Identifier*>(e)) {
            if (id->is_function_reference)
                err(e->source_line(), "elf backend v0: function values are not supported");
            auto it = ctx_->locals.find(id->name);
            if (it == ctx_->locals.end())
                err(e->source_line(), "elf backend v0: name '" + id->name + "' is not accessible here");
            E_.mov_r_mem(RAX, RBP, it->second);
            return;
        }
        if (auto* bin = dynamic_cast<BinaryExpr*>(e)) {
            compile_binary(bin);
            return;
        }
        if (auto* n = dynamic_cast<NotExpr*>(e)) {
            if (!is_word(n->operand->resolved_type))
                err(e->source_line(), "elf backend v0: 'not' requires an int/bool/char operand");
            compile_expr(n->operand.get());
            E_.alu_ri(ALU_CMP, RAX, 0);
            E_.setcc_al(CC_E);
            E_.movzx_q_b(RAX, RAX);
            return;
        }
        if (auto* n = dynamic_cast<NegExpr*>(e)) {
            if (!is_word(n->operand->resolved_type))
                err(e->source_line(), "elf backend v0: unary '-' requires an int/bool/char operand");
            compile_expr(n->operand.get());
            E_.neg_r(RAX);
            return;
        }
        if (auto* c = dynamic_cast<ConditionalExpr*>(e)) {
            if (!is_word(c->condition->resolved_type))
                err(e->source_line(), "elf backend v0: conditional condition must be int/bool/char");
            int else_l = new_label();
            int end_l = new_label();
            compile_expr(c->condition.get());
            E_.test_rr(RAX, RAX);
            E_.jcc(CC_E, else_l);
            compile_expr(c->then_expr.get());
            E_.jmp(end_l);
            bind(else_l);
            compile_expr(c->else_expr.get());
            bind(end_l);
            return;
        }
        if (auto* cst = dynamic_cast<CastExpr*>(e)) {
            if (!is_word(cst->operand->resolved_type))
                err(e->source_line(), "elf backend v0: cast operand must be int/bool/char");
            compile_expr(cst->operand.get());
            if (cst->target_type == TypeKind::Char) {
                if (cst->operand->resolved_type != TypeKind::Char)
                    E_.movsx_q_b(RAX, RAX);   // int -> char: truncate + sign-extend
                return;
            }
            if (cst->target_type == TypeKind::Int)
                return;                        // bool/char -> int: identity (already sign-extended qwords)
            err(e->source_line(), "elf backend v0: unsupported cast target");
        }
        if (auto* call = dynamic_cast<CallExpr*>(e)) {
            compile_call(call);
            return;
        }
        err(e->source_line(), "elf backend v0: unsupported expression (build with the C backend)");
    }

    void compile_binary(BinaryExpr* e) {
        TypeKind lt = e->left->resolved_type;
        TypeKind rt = e->right->resolved_type;
        if (!is_word(lt) || !is_word(rt))
            err(e->source_line(), "elf backend v0: operand types of '" + e->op + "' are unsupported (int/bool/char only)");

        const std::string& op = e->op;
        if (op == "&&" || op == "||") {
            int skip_l = new_label();
            int end_l = new_label();
            compile_expr(e->left.get());
            E_.test_rr(RAX, RAX);
            E_.jcc(op == "&&" ? CC_E : CC_NE, skip_l);
            compile_expr(e->right.get());
            // canonicalize the right result to 0/1 and fall through
            E_.test_rr(RAX, RAX);
            E_.setcc_al(CC_NE);
            E_.movzx_q_b(RAX, RAX);
            E_.jmp(end_l);
            bind(skip_l);
            E_.mov_r_imm(RAX, op == "&&" ? 0 : 1);
            bind(end_l);
            return;
        }

        compile_expr(e->left.get());
        E_.push_r(RAX);
        ctx_->pending++;
        compile_expr(e->right.get());
        E_.mov_r_r(RCX, RAX);            // right operand
        E_.pop_r(RAX);
        ctx_->pending--;                 // left operand

        if (op == "+") { E_.alu_rr(ALU_ADD, RAX, RCX); return; }
        if (op == "-") { E_.alu_rr(ALU_SUB, RAX, RCX); return; }
        if (op == "*") { E_.imul_rr(RAX, RCX); return; }
        if (op == "/" || op == "%") {
            E_.cqo();
            E_.idiv_r(RCX);
            if (op == "%") E_.mov_r_r(RAX, RDX);
            return;
        }
        int cc = op == "==" ? CC_E   : op == "!=" ? CC_NE : op == "<"  ? CC_L :
                 op == "<=" ? CC_LE  : op == ">"  ? CC_G  : op == ">=" ? CC_GE : -1;
        if (cc < 0)
            err(e->source_line(), "elf backend v0: unsupported operator '" + op + "'");
        E_.alu_rr(ALU_CMP, RAX, RCX);
        E_.setcc_al(cc);
        E_.movzx_q_b(RAX, RAX);
    }

    // ── user function calls ──────────────────────────────────────────────────
    void compile_call(CallExpr* c) {
        if (c->is_struct_ctor)         err(c->source_line(), "elf backend v0: structs are not supported");
        if (c->is_partial)             err(c->source_line(), "elf backend v0: partial application is not supported");
        if (c->is_function_value_call) err(c->source_line(), "elf backend v0: function values are not supported");
        auto it = fns_by_name_.find(c->name);
        if (it == fns_by_name_.end()) {
            // ord is the only word builtin in the zero-dependency runtime.
            if (c->name == "ord") {
                compile_expr(c->args[0].get());
                E_.movzx_q_b(RAX, RAX);
                return;
            }
            err(c->source_line(), "elf backend v0: builtin '" + c->name + "' is not supported (build with the C backend)");
        }
        FunctionDecl* fn = it->second;
        size_t n = c->args.size();
        if (n != fn->params.size())
            err(c->source_line(), "elf backend v0: argument count mismatch for '" + fn->name + "'");
        if (n > 6)
            err(c->source_line(), "elf backend v0: too many call arguments (max 6)");

        // SysV plan: word args fill CALL_REGS in order. Every argument is
        // spilled on the stack exactly once, then popped in reverse.
        for (size_t i = 0; i < n; i++) {
            compile_expr(c->args[i].get());
            E_.push_r(RAX);
            ctx_->pending++;
        }
        for (size_t k = n; k-- > 0;) {
            E_.pop_r(RAX);
            ctx_->pending--;
            E_.mov_r_r(CALL_REGS[k], RAX);
        }
        emit_call(fn_label(fn));
    }

    int fn_label(FunctionDecl* fn) {
        if (fn == main_fn_) return ctx_main_.label_id;
        auto* c = fn_ctx_[fn];
        return c->label_id;
    }

    // ── print (printf replaced by byte-exact helper calls) ───────────────────
    void emit_print(PrintStmt* s) {
        for (size_t i = 0; i < s->args.size(); i++) {
            if (!is_word(s->args[i]->resolved_type))
                err(s->line, "elf backend v0: print argument types are unsupported (int/bool/char only)");
        }
        for (size_t i = 0; i < s->args.size(); i++) {
            if (i > 0) emit_wchr_imm(' ');
            compile_expr(s->args[i].get());
            bool as_char = s->args[i]->resolved_type == TypeKind::Char;
            E_.mov_r_r(RDI, RAX);
            emit_call(rt_label(as_char ? "_hmx_w_char" : "_hmx_w_i64", s->line));
        }
        emit_wchr_imm('\n');
    }

    // ── statements ───────────────────────────────────────────────────────────
    const int& slot_of(const std::string& name, int line) {
        auto it = ctx_->locals.find(name);
        if (it == ctx_->locals.end())
            err(line, "elf backend v0: name '" + name + "' is not assignable here");
        return it->second;
    }

    void require_word_condition(Expression* e, const char* where) {
        if (!is_word(e->resolved_type))
            err(e->source_line(), std::string("elf backend v0: ") + where + " must be int/bool/char");
    }

    void emit_node(Ctx& c, const ir::Node& n) {
        ctx_ = &c;
        switch (n.kind) {
            case ir::SKind::VarDecl: {
                auto* v = static_cast<VarDecl*>(n.ast);
                auto ds = decl_slots_.find(v);
                if (ds == decl_slots_.end())
                    err(v->line, "elf backend v0: internal: undeclared name '" + v->name + "'");
                const int off = ds->second;
                c.locals[v->name] = off;   // bind the name for this scope
                if (!v->initializer) {
                    E_.mov_r_imm(RAX, 0);
                    E_.mov_mem_r(RBP, off, RAX);
                    return;
                }
                compile_expr(v->initializer.get());
                E_.mov_mem_r(RBP, off, RAX);
                return;
            }
            case ir::SKind::Assign: {
                auto* s = static_cast<AssignStmt*>(n.ast);
                const int& off = slot_of(s->name, s->line);
                TypeKind rhs_t = s->rhs ? s->rhs->resolved_type : TypeKind::Int;
                if (s->op == "=") {
                    compile_expr(s->rhs.get());
                    E_.mov_mem_r(RBP, off, RAX);
                    return;
                }
                if (s->op == "++" || s->op == "--") {
                    if (rhs_t == TypeKind::Decimal)
                        err(s->line, "elf backend v0: '++'/'--' is not supported on decimals");
                    E_.alu_mi(s->op == "++" ? ALU_ADD : ALU_SUB, RBP, off, 1);
                    return;
                }
                if (rhs_t == TypeKind::Decimal || rhs_t == TypeKind::Text)
                    err(s->line, "elf backend v0: compound assignment on decimals/text is not supported");
                compile_expr(s->rhs.get());
                E_.mov_r_r(RCX, RAX);
                E_.mov_r_mem(RAX, RBP, off);
                const std::string& op = s->op;
                if (op == "+=") E_.alu_rr(ALU_ADD, RAX, RCX);
                else if (op == "-=") E_.alu_rr(ALU_SUB, RAX, RCX);
                else if (op == "*=") E_.imul_rr(RAX, RCX);
                else if (op == "/=" || op == "%=") {
                    E_.cqo();
                    E_.idiv_r(RCX);
                    if (op == "%=") E_.mov_r_r(RAX, RDX);
                } else err(s->line, "elf backend v0: unsupported assignment operator '" + op + "'");
                E_.mov_mem_r(RBP, off, RAX);
                return;
            }
            case ir::SKind::ExprStmt: {
                auto* s = static_cast<ExprStmt*>(n.ast);
                compile_expr(s->expr.get());
                return;   // word results are register-only discards in v0
            }
            case ir::SKind::Print:
                emit_print(static_cast<PrintStmt*>(n.ast));
                return;
            case ir::SKind::If: {
                auto* s = static_cast<IfStmt*>(n.ast);
                compile_expr(s->condition.get());
                require_word_condition(s->condition.get(), "if condition");
                int else_l = new_label();
                int end_l = new_label();
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_E, s->has_else ? else_l : end_l);
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                if (s->has_else) {
                    E_.jmp(end_l);
                    bind(else_l);
                    emit_scope(c, [&] {
                        for (auto& b : n.else_body) emit_node(c, *b);
                    });
                }
                bind(end_l);
                return;
            }
            case ir::SKind::While: {
                auto* s = static_cast<WhileStmt*>(n.ast);
                int top_l = new_label();
                int end_l = new_label();
                bind(top_l);
                compile_expr(s->condition.get());
                require_word_condition(s->condition.get(), "while condition");
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_E, end_l);
                c.loops.push_back({end_l, top_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                E_.jmp(top_l);
                bind(end_l);
                return;
            }
            case ir::SKind::DoWhile: {
                auto* s = static_cast<DoWhileStmt*>(n.ast);
                int top_l = new_label();
                int end_l = new_label();
                int cont_l = new_label();
                bind(top_l);
                c.loops.push_back({end_l, cont_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                bind(cont_l);
                compile_expr(s->condition.get());
                require_word_condition(s->condition.get(), "do-while condition");
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_NE, top_l);
                bind(end_l);
                return;
            }
            case ir::SKind::For: {
                auto* s = static_cast<ForStmt*>(n.ast);
                int top_l = new_label();
                int end_l = new_label();
                // the header declaration is scoped to header + body
                std::string hdr;
                bool had = false;
                int prev = 0;
                if (n.init && n.init->kind == ir::SKind::VarDecl) {
                    hdr = static_cast<VarDecl*>(n.init->ast)->name;
                    auto it = c.locals.find(hdr);
                    if (it != c.locals.end()) { had = true; prev = it->second; }
                }
                if (n.init) emit_node(c, *n.init);
                bind(top_l);
                if (s->condition) {
                    compile_expr(s->condition.get());
                    require_word_condition(s->condition.get(), "for condition");
                } else {
                    E_.mov_r_imm(RAX, 1);
                }
                E_.test_rr(RAX, RAX);
                E_.jcc(CC_E, end_l);
                int cont_l = new_label();
                c.loops.push_back({end_l, cont_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                bind(cont_l);
                if (n.update) emit_node(c, *n.update);
                E_.jmp(top_l);
                bind(end_l);
                if (had) c.locals[hdr] = prev;
                else if (!hdr.empty()) c.locals.erase(hdr);
                return;
            }
            case ir::SKind::Loop: {
                auto* s = static_cast<LoopStmt*>(n.ast);
                auto slots = loop_slots_[s];
                int top_l = new_label();
                int end_l = new_label();
                compile_expr(s->count.get());
                E_.mov_mem_r(RBP, slots.first, RAX);
                E_.mov_r_imm(RAX, 0);
                E_.mov_mem_r(RBP, slots.second, RAX);
                bind(top_l);
                E_.mov_r_mem(RAX, RBP, slots.second);
                E_.alu_rm(ALU_CMP, RAX, RBP, slots.first);
                E_.jcc(CC_GE, end_l);
                int cont_l = new_label();
                c.loops.push_back({end_l, cont_l});
                emit_scope(c, [&] {
                    for (auto& b : n.body) emit_node(c, *b);
                });
                c.loops.pop_back();
                bind(cont_l);
                E_.alu_mi(ALU_ADD, RBP, slots.second, 1);
                E_.jmp(top_l);
                bind(end_l);
                return;
            }
            case ir::SKind::Break:
                if (c.loops.empty()) err(n.ast->line, "elf backend v0: break outside a loop");
                E_.jmp(c.loops.back().brk);
                return;
            case ir::SKind::Continue:
                if (c.loops.empty()) err(n.ast->line, "elf backend v0: continue outside a loop");
                E_.jmp(c.loops.back().cont);
                return;
            case ir::SKind::Return: {
                auto* s = static_cast<ReturnStmt*>(n.ast);
                if (!s->values.empty()) {
                    if (s->values.size() > 1)
                        err(s->line, "elf backend v0: multi-value return is a tuple (not supported)");
                    if (!is_word(s->values[0]->resolved_type))
                        err(s->line, "elf backend v0: return type is unsupported (int/bool/char only)");
                    compile_expr(s->values[0].get());
                    E_.mov_mem_r(RBP, c.ret_slot, RAX);
                }
                E_.jmp(c.ret_label);
                return;
            }
            case ir::SKind::Defer:
                err(n.ast->line, "elf backend v0: defer is not supported");
                return;
            case ir::SKind::Try:
                err(n.ast->line, "elf backend v0: try/catch is not supported");
                return;
            case ir::SKind::Switch:
                err(n.ast->line, "elf backend v0: switch is not supported");
                return;
            case ir::SKind::Foreach:
                err(n.ast->line, "elf backend v0: foreach is not supported");
                return;
            case ir::SKind::MultiAssign:
            case ir::SKind::DestructDecl:
            case ir::SKind::ArrayAssign:
            case ir::SKind::ElementAssign:
            case ir::SKind::MemberAssign:
                err(n.ast->line, "elf backend v0: array/tuple/struct assignment is not supported");
                return;
            case ir::SKind::TypeDecl:
                err(n.ast->line, "elf backend v0: type declarations are not supported");
                return;
            case ir::SKind::FuncDecl:
                return;  // registered up front
        }
    }

private:
    // Emit-side mirror of scan_scope: unbind names the block declared so a
    // later sibling block rebinds cleanly through its own declaration.
    template <typename F>
    void emit_scope(Ctx& c, F&& f) {
        std::map<std::string, int> before(c.locals);
        f();
        for (auto it = c.locals.begin(); it != c.locals.end();) {
            if (before.count(it->first) == 0) it = c.locals.erase(it);
            else ++it;
        }
    }

    void check_fn_signature(FunctionDecl* fn) {
        for (auto& p : fn->params) {
            if (!is_word(p.type))
                err(fn->line, "elf backend v0: parameter type of '" + fn->name + "' is unsupported (int/bool/char only)");
        }
        if (fn->has_return_type && !is_word(fn->return_type))
            err(fn->line, "elf backend v0: return type of '" + fn->name + "' is unsupported");
    }

    void emit_function(FunctionDecl* fn) {
        Ctx& c = *fn_ctx_[fn];
        bind(c.label_id);
        emit_frame_head(c);
        // park register args into their slots (SysV: words in CALL_REGS)
        for (size_t i = 0; i < fn->params.size(); i++) {
            int off = c.locals[fn->params[i].name];
            E_.mov_mem_r(RBP, off, CALL_REGS[i]);
            (void)off;
        }

        auto body_ir = ir::build(fn->body);
        for (auto& n : body_ir) emit_node(c, *n);
        emit_frame_tail(c);
    }
};

}  // namespace (internal)

std::vector<uint8_t> emit_elf(Program& program, const std::string& source_file) {
    ElfBackend backend(program, source_file);
    return backend.run();
}

}  // namespace backend
